using Clock=chrono::steady_clock;
static int64_t nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static string trim(string s){size_t a=0,b=s.size();while(a<b&&(s[a]==' '||s[a]=='\t'||s[a]=='\r'||s[a]=='\n'))++a;while(b>a&&(s[b-1]==' '||s[b-1]=='\t'||s[b-1]=='\r'||s[b-1]=='\n'))--b;return s.substr(a,b-a);}
static bool number(const string&s,uint64_t&v){if(s.empty())return false;v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(UINT64_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return true;}
static bool tokenchar(unsigned char c){return (c>='0'&&c<='9')||(c>='a'&&c<='z')||(c>='A'&&c<='Z')||strchr("!#$%&'*+-.^_`|~",c);}
static bool has_token(const string &s,const string&t){size_t p=0;while(p<=s.size()){size_t q=s.find(',',p);if(q==string::npos)q=s.size();if(lower(trim(s.substr(p,q-p)))==t)return true;if(q==s.size())break;p=q+1;}return false;}
struct Config {sockaddr_in listen{},origin{};string root;int maxconn=0,header=0,htime=0,idle=0,wtime=0,maxreq=0,depth=0;uint64_t cachebytes=0,ttl=0;};
static bool addr(const string&s,sockaddr_in &a){size_t p=s.rfind(':');if(p==string::npos)return false;string ip=s.substr(0,p);uint64_t n;if(!number(s.substr(p+1),n)||n==0||n>65535)return false;a={};a.sin_family=AF_INET;a.sin_port=htons(n);return inet_pton(AF_INET,ip.c_str(),&a.sin_addr)==1;}
static bool config(int argc,char**argv,Config&c){if(argc!=3||string(argv[1])!="--config")return false;ifstream f(argv[2]);if(!f)return false;unordered_map<string,string> m;string line;unordered_set<string> allowed={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","cache_bytes","cache_ttl_ms"};while(getline(f,line)){line=trim(line);if(line.empty()||line[0]=='#')continue;auto p=line.find('=');if(p==string::npos)return false;string k=trim(line.substr(0,p)),v=trim(line.substr(p+1));if(!allowed.count(k)||m.count(k)||v.empty())return false;m[k]=v;}if(m.size()!=allowed.size()||!addr(m["listen"],c.listen)||!addr(m["origin_address"],c.origin))return false;c.root=m["root"];struct stat st{};if(c.root.empty()||c.root[0]!='/'||stat(c.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;auto get=[&](const char*k,int &x){uint64_t v;if(!number(m[k],v)||v==0||v>INT_MAX)return false;x=(int)v;return true;};if(!get("max_connections",c.maxconn)||!get("header_bytes",c.header)||!get("header_timeout_ms",c.htime)||!get("idle_timeout_ms",c.idle)||!get("write_timeout_ms",c.wtime)||!get("max_requests",c.maxreq)||!get("pipeline_depth",c.depth))return false;if(!number(m["cache_bytes"],c.cachebytes)||!c.cachebytes||!number(m["cache_ttl_ms"],c.ttl)||!c.ttl||c.ttl>INT_MAX)return false;return true;}
struct Header{string name,value;};
struct Request{string method,target,path,host,language,version;vector<Header> headers;bool close=false,head=false,gateway=false,bypass=false;};
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;uint32_t v,min;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;min=0x80;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;min=0x800;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;min=0x10000;}else return false;if(i+n>s.size())return false;while(n--){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;v=(v<<6)|(d&63);}if(v<min||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hexval(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int parse_request(const string&s,Request&r){for(size_t i=0;i<s.size();i++){unsigned char c=s[i];if(!c)return 400;if(c=='\n'&&(i==0||s[i-1]!='\r'))return 400;if(c=='\r'&&(i+1>=s.size()||s[i+1]!='\n'))return 400;}size_t end=s.find("\r\n");if(end==string::npos)return 400;string line=s.substr(0,end);size_t a=line.find(' '),b=a==string::npos?a:line.find(' ',a+1);if(a==string::npos||b==string::npos||line.find(' ',b+1)!=string::npos||a==0||b==a+1||b+1==line.size())return 400;r.method=line.substr(0,a);for(unsigned char c:r.method)if(!tokenchar(c))return 400;r.target=line.substr(a+1,b-a-1);r.version=line.substr(b+1);if(r.version!="HTTP/1.1"&&r.version!="HTTP/1.0")return 400;if(r.target.empty()||r.target[0]!='/'||r.target.find('#')!=string::npos)return 400;for(unsigned char c:r.target)if(c<=32||c==127||c=='\\')return 400;size_t q=r.target.find('?');string raw=r.target.substr(0,q);for(size_t i=0;i<raw.size();i++){unsigned char c=raw[i];if(c=='%'){if(i+2>=raw.size())return 400;int x=hexval(raw[i+1]),y=hexval(raw[i+2]);if(x<0||y<0)return 400;c=(x<<4)|y;i+=2;}if(!c||c=='\\')return 400;r.path.push_back(c);}if(!utf8(r.path))return 400;size_t p=0;while(p<=r.path.size()){size_t z=r.path.find('/',p);if(z==string::npos)z=r.path.size();if(r.path.substr(p,z-p)=="..")return 403;if(z==r.path.size())break;p=z+1;}int hosts=0,cls=0;bool te=false;string conn;size_t cur=end+2;while(cur<s.size()-2){size_t n=s.find("\r\n",cur);if(n==string::npos||n==cur)return 400;string h=s.substr(cur,n-cur);size_t colon=h.find(':');if(colon==string::npos||colon==0)return 400;string name=h.substr(0,colon);for(unsigned char c:name)if(!tokenchar(c))return 400;string value=trim(h.substr(colon+1));for(unsigned char c:value)if((c<32&&c!='\t')||c==127)return 400;name=lower(name);r.headers.push_back({name,value});if(name=="host"){hosts++;r.host=value;}else if(name=="content-length"){cls++;uint64_t v;if(!number(value,v)||v!=0)return 400;}else if(name=="transfer-encoding")te=true;else if(name=="connection")conn+=","+value;else if(name=="accept-language"){if(!r.language.empty())r.language+=", ";r.language+=value;}if(name=="authorization"||name=="cookie"||name=="range"||name=="if-none-match"||name=="if-modified-since"||name=="if-match"||name=="if-unmodified-since"||name=="if-range"||name=="cache-control"||name=="pragma")r.bypass=true;cur=n+2;}if(cls>1||te)return 400;r.gateway=r.path.rfind("/gateway/",0)==0;if(r.gateway&&(hosts!=1||r.host.empty()))return 400;if(hosts>1)return 400;r.close=r.version=="HTTP/1.0"||has_token(conn,"close");r.head=r.method=="HEAD";return 0;}
static const char* reason(int n){switch(n){case 200:return "OK";case 201:return "Created";case 204:return "No Content";case 301:return "Moved Permanently";case 302:return "Found";case 304:return "Not Modified";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";case 500:return "Internal Server Error";case 502:return "Bad Gateway";default:return "Response";}}
struct Response{int status=200;vector<Header> headers;shared_ptr<string> body=make_shared<string>();uint64_t length=0;string etag;bool cacheable=false;uint64_t age_ms=0;};
struct Client{int fd;uint64_t id;string input,outhead;size_t hpos=0,bpos=0;shared_ptr<string> body;bool suppress=false,closing=false,waiting=false;int requests=0;int64_t last=0,first=0,write_last=0;Request req;};
struct Origin{int fd;int client;uint64_t id;string key,sendbuf,input;size_t sent=0;bool connecting=true,parsed=false,head=false;int64_t last=0;Response response;uint64_t need=0;};
struct Entry{Response r;int64_t expires;list<string>::iterator lru;};
class Server{Config cfg;int ep=-1,lfd=-1,rootfd=-1;uint64_t nextid=1,used=0;unordered_map<int,unique_ptr<Client>> clients;unordered_map<int,unique_ptr<Origin>> origins;unordered_map<string,Entry> cache;list<string> lru;
void mod(int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);}void add(int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e);}void del(int fd){epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);}void closeclient(int fd){auto it=clients.find(fd);if(it==clients.end())return;del(fd);clients.erase(it);}void closeorigin(int fd){auto it=origins.find(fd);if(it==origins.end())return;del(fd);origins.erase(it);}
string cachekey(const Request&r){return to_string(r.host.size())+":"+r.host+to_string(r.target.size())+":"+r.target+to_string(r.language.size())+":"+r.language;}
void erasecache(unordered_map<string,Entry>::iterator it){used-=it->second.r.body->size();lru.erase(it->second.lru);cache.erase(it);}void store(const string&key,const Response&r,int64_t t){auto old=cache.find(key);if(old!=cache.end())erasecache(old);if(!r.cacheable||r.body->size()>cfg.cachebytes)return;while(used+r.body->size()>cfg.cachebytes&&!lru.empty()){auto it=cache.find(lru.back());if(it==cache.end()){lru.pop_back();continue;}erasecache(it);}lru.push_front(key);Entry e{r,t+(int64_t)r.age_ms,lru.begin()};used+=r.body->size();cache.emplace(key,move(e));}
void respond(Client&c,const Response&r,bool malformed=false){c.waiting=false;c.requests++;bool closeit=malformed||c.req.close||c.requests>=cfg.maxreq;c.closing=closeit;c.suppress=c.req.head||r.status==204||r.status==304;c.outhead="HTTP/1.1 "+to_string(r.status)+" "+reason(r.status)+"\r\n";for(auto &h:r.headers)c.outhead+=h.name+": "+h.value+"\r\n";c.outhead+="Content-Length: "+to_string(r.length)+"\r\nConnection: "+string(closeit?"close":"keep-alive")+"\r\n\r\n";c.hpos=c.bpos=0;c.body=r.body;c.write_last=nowms();mod(c.fd,EPOLLOUT);}
void error(Client&c,int code,bool malformed=false){Response r;r.status=code;r.length=0;respond(c,r,malformed);}
int openfile(const string&path){int cur=dup(rootfd);if(cur<0)return -500;size_t p=1;while(p<=path.size()){size_t q=path.find('/',p);if(q==string::npos)q=path.size();string part=path.substr(p,q-p);if(part.empty()||part=="."){if(q==path.size())break;p=q+1;continue;}bool last=q==path.size();int flags=O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK;if(!last)flags|=O_DIRECTORY;int next=openat(cur,part.c_str(),flags);if(next<0){int e=errno;struct stat st{};bool sym=fstatat(cur,part.c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);close(cur);if(sym||e==ELOOP||e==EACCES||e==EPERM)return -403;if(e==ENOENT||e==ENOTDIR)return -404;return -403;}close(cur);cur=next;p=q+1;}struct stat st{};if(fstat(cur,&st)||!S_ISREG(st.st_mode)){close(cur);return -403;}if(path.back()=='/'){close(cur);return -403;}return cur;}
void local(Client&c){int fd=openfile(c.req.path);if(fd<0){error(c,-fd);return;}struct stat st{};if(fstat(fd,&st)||st.st_size<0){close(fd);error(c,500);return;}Response r;r.length=st.st_size;r.headers.push_back({"Content-Type","application/octet-stream"});if(!c.req.head){try{r.body->resize(st.st_size);}catch(...){close(fd);error(c,500);return;}size_t p=0;while(p<r.body->size()){ssize_t n=read(fd,r.body->data()+p,r.body->size()-p);if(n>0)p+=n;else if(n<0&&errno==EINTR)continue;else{close(fd);error(c,500);return;}}}close(fd);respond(c,r);}
static bool hop(const string&n){return n=="connection"||n=="proxy-connection"||n=="keep-alive"||n=="te"||n=="trailer"||n=="transfer-encoding"||n=="upgrade"||n=="content-length";}
void startorigin(Client&c,const string&key,const string&etag){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0){error(c,502);return;}int rc=connect(fd,(sockaddr*)&cfg.origin,sizeof(cfg.origin));if(rc<0&&errno!=EINPROGRESS){close(fd);error(c,502);return;}auto o=make_unique<Origin>();o->fd=fd;o->client=c.fd;o->id=c.id;o->key=key;o->head=c.req.head;o->last=nowms();string target=c.req.target;size_t qs=target.find('?');string rawpath=target.substr(0,qs);if(rawpath.rfind("/gateway/",0)==0)target=target.substr(8);else {target=c.req.path.substr(8)+(qs==string::npos?"":target.substr(qs));}o->sendbuf=c.req.method+" "+target+" HTTP/1.1\r\nHost: "+c.req.host+"\r\n";string connection;for(auto &h:c.req.headers)if(h.name=="connection")connection+=","+h.value;for(auto &h:c.req.headers){if(h.name=="host"||hop(h.name)||has_token(connection,h.name)||(!etag.empty()&&h.name=="if-none-match"))continue;o->sendbuf+=h.name+": "+h.value+"\r\n";}if(!etag.empty())o->sendbuf+="If-None-Match: "+etag+"\r\n";o->sendbuf+="Content-Length: 0\r\nConnection: close\r\n\r\n";c.waiting=true;mod(c.fd,0);origins.emplace(fd,move(o));add(fd,EPOLLOUT);}
void handle(Client&c){Request r;int code=parse_request(c.input,r);c.req=move(r);if(code){error(c,code,true);return;}if(c.req.method!="GET"&&c.req.method!="HEAD"){error(c,405);return;}if(!c.req.gateway){local(c);return;}string key=cachekey(c.req);auto it=cache.find(key);int64_t t=nowms();if(!c.req.bypass&&it!=cache.end()&&it->second.expires>t){lru.splice(lru.begin(),lru,it->second.lru);respond(c,it->second.r);return;}string etag;if(!c.req.head&&!c.req.bypass&&it!=cache.end())etag=it->second.r.etag;startorigin(c,c.req.bypass||c.req.head?string():key,etag);}
void consume(Client&c){if(c.waiting||!c.outhead.empty())return;size_t e=c.input.find("\r\n\r\n");if(e!=string::npos){if(e+4>(size_t)cfg.header){c.req=Request();error(c,431,true);return;}string rest=c.input.substr(e+4);c.input.resize(e+4);handle(c);c.input=move(rest);c.first=c.input.empty()?0:nowms();return;}if(c.input.size()>=(size_t)cfg.header){c.req=Request();error(c,431,true);return;}for(size_t i=0;i<c.input.size();i++){if(!c.input[i]||(c.input[i]=='\n'&&(i==0||c.input[i-1]!='\r'))||(c.input[i]=='\r'&&i+1<c.input.size()&&c.input[i+1]!='\n')){c.req=Request();error(c,400,true);return;}}}
void readclient(Client&c){char buf[16384];for(;;){size_t space=(size_t)cfg.header-c.input.size();if(!space){consume(c);return;}ssize_t n=recv(c.fd,buf,min(space,sizeof(buf)),0);if(n>0){int64_t t=nowms();if(c.input.empty())c.first=t;c.last=t;c.input.append(buf,n);consume(c);if(c.waiting||!c.outhead.empty())return;continue;}if(n==0){closeclient(c.fd);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return;closeclient(c.fd);return;}}
void writeclient(Client&c){while(true){iovec v[2];int cnt=0;if(c.hpos<c.outhead.size()){v[cnt++]={c.outhead.data()+c.hpos,c.outhead.size()-c.hpos};}if(!c.suppress&&c.body&&c.bpos<c.body->size())v[cnt++]={c.body->data()+c.bpos,c.body->size()-c.bpos};if(!cnt){int fd=c.fd;if(c.closing){closeclient(fd);return;}c.outhead.clear();c.body.reset();c.last=nowms();mod(fd,EPOLLIN);consume(c);return;}msghdr msg{};msg.msg_iov=v;msg.msg_iovlen=cnt;ssize_t n=sendmsg(c.fd,&msg,MSG_NOSIGNAL);if(n>0){c.write_last=nowms();size_t a=min<size_t>(n,c.outhead.size()-c.hpos);c.hpos+=a;c.bpos+=n-a;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;closeclient(c.fd);return;}}
static void policy(Response&r,const Config&cfg){r.cacheable=r.status==200;r.age_ms=cfg.ttl;bool privateflag=false;for(auto &h:r.headers){string n=lower(h.name);if(n=="set-cookie")privateflag=true;if(n=="etag")r.etag=h.value;if(n=="vary"){size_t p=0;while(p<=h.value.size()){size_t q=h.value.find(',',p);if(q==string::npos)q=h.value.size();string v=lower(trim(h.value.substr(p,q-p)));if(v!="accept-language")privateflag=true;if(q==h.value.size())break;p=q+1;}}if(n=="cache-control"){size_t p=0;while(p<=h.value.size()){size_t q=h.value.find(',',p);if(q==string::npos)q=h.value.size();string d=lower(trim(h.value.substr(p,q-p)));size_t z=d.find('=');string name=trim(d.substr(0,z));if(name=="private"||name=="no-store")privateflag=true;if(name=="no-cache")r.age_ms=0;if(name=="max-age"||name=="s-maxage"){if(z==string::npos)r.age_ms=0;else{string val=trim(d.substr(z+1));if(val.size()>=2&&val.front()=='"'&&val.back()=='"')val=val.substr(1,val.size()-2);uint64_t x;if(!number(val,x))r.age_ms=0;else r.age_ms=min(r.age_ms,x>UINT64_MAX/1000?UINT64_MAX:x*1000);}}if(q==h.value.size())break;p=q+1;}}}if(privateflag)r.cacheable=false;}
bool parseorigin(Origin&o){size_t e=o.input.find("\r\n\r\n");if(e==string::npos)return false;string hs=o.input.substr(0,e+4);for(size_t i=0;i<hs.size();i++)if(!hs[i]||(hs[i]=='\n'&&(i==0||hs[i-1]!='\r'))||(hs[i]=='\r'&&(i+1==hs.size()||hs[i+1]!='\n')))return false;size_t pos=hs.find("\r\n");string line=hs.substr(0,pos);if(line.size()<12||line.substr(0,5)!="HTTP/"||line[8]!=' '||!isdigit((unsigned char)line[9])||!isdigit((unsigned char)line[10])||!isdigit((unsigned char)line[11]))return false;int status=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';if(status<200||status>599)return false;o.response.status=status;int cls=0;uint64_t len=0;bool te=false;vector<Header> all;string con;size_t p=pos+2;while(p<e){size_t q=hs.find("\r\n",p);if(q==string::npos||q>e)return false;string h=hs.substr(p,q-p);size_t z=h.find(':');if(z==string::npos||!z)return false;string n=lower(h.substr(0,z));for(unsigned char c:n)if(!tokenchar(c))return false;string v=trim(h.substr(z+1));for(unsigned char c:v)if((c<32&&c!='\t')||c==127)return false;if(n=="content-length"){cls++;if(!number(v,len))return false;}if(n=="transfer-encoding")te=true;if(n=="connection")con+=","+v;all.push_back({n,v});p=q+2;}if(te||cls>1||(!cls&&status!=304&&status!=204))return false;for(auto&h:all)if(!hop(h.name)&&!has_token(con,h.name))o.response.headers.push_back(h);o.response.length=len;o.need=(o.head||status==304||status==204)?0:len;if(o.need>268435456)return false;o.response.body=make_shared<string>();o.input.erase(0,e+4);o.parsed=true;policy(o.response,cfg);return true;}
void finishorigin(int fd,bool ok){auto it=origins.find(fd);if(it==origins.end())return;Origin &o=*it->second;auto ci=clients.find(o.client);if(ci!=clients.end()&&ci->second->id==o.id&&ci->second->waiting){Client &c=*ci->second;if(!ok)error(c,502);else {Response r=o.response;if(r.status==304&&!o.key.empty()){auto old=cache.find(o.key);if(old!=cache.end()){Response saved=old->second.r;for(auto&h:r.headers){if(h.name=="etag"||h.name=="cache-control"||h.name=="vary"||h.name=="expires"){saved.headers.erase(remove_if(saved.headers.begin(),saved.headers.end(),[&](const Header&x){return lower(x.name)==h.name;}),saved.headers.end());saved.headers.push_back(h);}}policy(saved,cfg);store(o.key,saved,nowms());respond(c,saved);}else respond(c,r);}else{if(!o.key.empty()&&r.status==200)store(o.key,r,nowms());respond(c,r);}}}closeorigin(fd);}
void origin_event(int fd,uint32_t events){auto it=origins.find(fd);if(it==origins.end())return;Origin&o=*it->second;if(events&EPOLLOUT){if(o.connecting){int err=0;socklen_t n=sizeof(err);if(getsockopt(fd,SOL_SOCKET,SO_ERROR,&err,&n)||err){finishorigin(fd,false);return;}o.connecting=false;}while(o.sent<o.sendbuf.size()){ssize_t n=send(fd,o.sendbuf.data()+o.sent,o.sendbuf.size()-o.sent,MSG_NOSIGNAL);if(n>0){o.sent+=n;o.last=nowms();continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;finishorigin(fd,false);return;}mod(fd,EPOLLIN);}if(events&(EPOLLIN|EPOLLHUP|EPOLLERR)){char b[16384];for(;;){ssize_t n=recv(fd,b,sizeof(b),0);if(n>0){o.last=nowms();if(!o.parsed){o.input.append(b,n);size_t e=o.input.find("\r\n\r\n");if(e==string::npos){if(o.input.size()>65536){finishorigin(fd,false);return;}continue;}if(e>65536||!parseorigin(o)){finishorigin(fd,false);return;}if(o.input.size()>o.need)o.input.resize(o.need);o.response.body->append(o.input);o.input.clear();}else{size_t left=o.need-o.response.body->size();o.response.body->append(b,min<size_t>(n,left));}if(o.parsed&&o.response.body->size()>=o.need){finishorigin(fd,true);return;}continue;}if(n==0){finishorigin(fd,false);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK){if(events&EPOLLERR)finishorigin(fd,false);return;}finishorigin(fd,false);return;}}}
public:explicit Server(Config c):cfg(move(c)){}bool init(){rootfd=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return false;lfd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(lfd<0)return false;int one=1;setsockopt(lfd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(lfd,(sockaddr*)&cfg.listen,sizeof(cfg.listen))||listen(lfd,4096))return false;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return false;add(lfd,EPOLLIN);return true;}
void run(){epoll_event ev[512];int64_t check=nowms();while(true){int n=epoll_wait(ep,ev,512,50);int64_t t=nowms();for(int i=0;i<n;i++){int fd=ev[i].data.fd;uint32_t e=ev[i].events;if(fd==lfd){while(true){int s=accept4(lfd,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0){if(errno==EINTR)continue;break;}if((int)clients.size()>=cfg.maxconn){close(s);continue;}auto c=make_unique<Client>();c->fd=s;c->id=nextid++;c->last=t;clients.emplace(s,move(c));add(s,EPOLLIN);}continue;}auto ci=clients.find(fd);if(ci!=clients.end()){if(e&EPOLLIN)readclient(*ci->second);ci=clients.find(fd);if(ci!=clients.end()&&(e&EPOLLOUT))writeclient(*ci->second);ci=clients.find(fd);if(ci!=clients.end()&&(e&(EPOLLERR|EPOLLHUP)))closeclient(fd);}else if(origins.count(fd))origin_event(fd,e);}if(t-check>=50){check=t;vector<int> dead;for(auto &kv:clients){Client&c=*kv.second;if(c.waiting)continue;if(!c.outhead.empty()){if(t-c.write_last>=cfg.wtime)dead.push_back(c.fd);}else if(c.first){if(t-c.first>=cfg.htime)dead.push_back(c.fd);}else if(t-c.last>=cfg.idle)dead.push_back(c.fd);}for(int fd:dead)closeclient(fd);dead.clear();for(auto &kv:origins)if(t-kv.second->last>=cfg.wtime)dead.push_back(kv.first);for(int fd:dead)finishorigin(fd,false);}}}
};
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);Config c;if(!config(argc,argv,c))return 1;Server s(c);if(!s.init())return 1;s.run();return 0;}
